package com.bank.risk.service;

import com.bank.risk.model.Order;
import com.bank.risk.repository.OrderRepository;

import java.util.*;
import java.util.logging.Logger;

public class RiskReviewService {
    private static final Logger log = Logger.getLogger(RiskReviewService.class.getName());
    private final OrderRepository repo;
    public RiskReviewService(OrderRepository repo) { this.repo = repo; }

    // One grouped pass with conditional counts, mirroring HAVING COUNT(CASE...)>0 AND ...
    public List<String> customersWithBothStates(String stateA, String stateB) {
        Map<String, int[]> counts = new TreeMap<>(); // [0]=countA, [1]=countB
        for (Order o : repo.findAll()) {
            int[] c = counts.computeIfAbsent(o.getCustomerId(), k -> new int[2]);
            if (stateA.equals(o.getStatus())) c[0]++;   // COUNT(CASE WHEN status=A)
            if (stateB.equals(o.getStatus())) c[1]++;   // COUNT(CASE WHEN status=B)
        }
        List<String> flagged = new ArrayList<>();
        for (Map.Entry<String, int[]> e : counts.entrySet()) {
            if (e.getValue()[0] > 0 && e.getValue()[1] > 0) { // HAVING both > 0
                flagged.add(e.getKey());
            }
        }
        log.warning(() -> "Customers with BOTH " + stateA + " and " + stateB + ": " + flagged);
        return flagged;
    }
}
